          "@type": "Question",
          "name": "How many stores left SNAP in 2026?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Between January 1 and November 5, 2026, 21,923 stores left SNAP. That is 8.8% of the stores authorized at the start of the year. The 2019 to 2025 average was 11,682."
          }
        },
        {
          "@type": "Question",
          "name": "Did the stocking rule cause stores to leave SNAP?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The rule's compliance date was November 4, 2026, so nearly all of these exits came before it. The data shows which stores left and where, but not why."
          }
        },
        {
          "@type": "Question",
          "name": "How much did SNAP enrollment drop in 2026?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "USDA counts 36.1 million people on SNAP in July 2026, down 13.2% from July 2025."
          }
        },
        {
          "@type": "Question",
          "name": "Which states had the largest drops in SNAP enrollment?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "From July 2025 to July 2026, Arizona fell 50.8%, Louisiana and Nevada 23.3%, Oklahoma 22.5%, and Florida 22.1%. Alaska was the only state that rose, by 3.5%."
          }
        },
        {
          "@type": "Question",
          "name": "Which counties have no SNAP store?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "On November 5, 2026, 22 counties had no SNAP store. Two of them, Hayes County, Nebraska, and Harding County, New Mexico, lost their last one in 2026."
          }
        }
      ]
